                    total_hashes,
                    opt_key[1] + 1,
                    new_bytes,
                    opt_key[3] + (leaves[end - 1][0],),
                )
            bill = (
                total_hashes if max_total_verify_hashes is not None else 0,
                new_bytes,
            )
            candidate = (new_key, cuts + ((start, end),))
